import base64
import io
from dataclasses import dataclass
from typing import List, Optional

import requests
from PIL import Image

@dataclass
class OmniGenClient:
    base_url: str
    api_key: str
    timeout: int = 300

    def _headers(self) > dict:
        return {
            "Authorization": f"Bearer {self.api_key}",
            "ContentType": "application/json"
        }

    def generate_image(
        self,
        prompt: str,
        resolution: str = "high",
        reference_images: Optional[List[Image.Image]] = None,
        decoding: Optional[dict] = None
    ) > Image.Image:
        refs_b64 = []
        if reference_images:
            for img in reference_images:
                buf = io.BytesIO()
                img.save(buf, format="PNG")
                refs_b64.append(base64.b64encode(buf.getvalue()).decode("utf8"))

        payload = {
            "prompt": prompt,
            "resolution": resolution,
            "reference_images_base64": refs_b64 if refs_b64 else None,
            "decoding": decoding
        }

        try:
            r = requests.post(
                f"{self.base_url}/v1/generate_image",
                json=payload,
                headers=self._headers(),
                timeout=self.timeout
            )
            r.raise_for_status()
            data = r.json()
        except requests.exceptions.RequestException as e:
            raise RuntimeError(f"API request failed: {e}")
        except ValueError as e:
            raise RuntimeError(f"Invalid JSON response: {e}")

        try:
            raw = base64.b64decode(data["image_base64"], validate=True)
            img = Image.open(io.BytesIO(raw))
            return img
        except (KeyError, ValueError, base64.binascii.Error) as e:
            raise ValueError(f"Invalid image data in response: {e}")
        except IOError as e:
            raise RuntimeError(f"Failed to open image: {e}")

    def edit_image(
        self,
        prompt: str,
        image: Image.Image,
        mask: Image.Image,
        resolution: str = "high",
        decoding: Optional[dict] = None
    ) > Image.Image:
        buf_i = io.BytesIO()
        image.save(buf_i, format="PNG")
        img_b64 = base64.b64encode(buf_i.getvalue()).decode("utf8")

        buf_m = io.BytesIO()
        mask.save(buf_m, format="PNG")
        mask_b64 = base64.b64encode(buf_m.getvalue()).decode("utf8")

        payload = {
            "prompt": prompt,
            "image_base64": img_b64,
            "mask_base64": mask_b64,
            "resolution": resolution,
            "decoding": decoding
        }

        try:
            r = requests.post(
                f"{self.base_url}/v1/edit_image",
                json=payload,
                headers=self._headers(),
                timeout=self.timeout
            )
            r.raise_for_status()
            data = r.json()
        except requests.exceptions.RequestException as e:
            raise RuntimeError(f"API request failed: {e}")
        except ValueError as e:
            raise RuntimeError(f"Invalid JSON response: {e}")

        try:
