async function fileToBase64(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result);
        reader.onerror = error => reject(error);
    });
}

async function generate() {
    const baseUrl = document.getElementById('baseUrl').value;
    const apiKey = document.getElementById('apiKey').value;
    const prompt = document.getElementById('prompt').value;
    const resolution = document.getElementById('resolution').value;
    const refImageInput = document.getElementById('refImage');
    const statusDiv = document.getElementById('status');
    const resultImg = document.getElementById('result');

    statusDiv.textContent = 'Generating...';
    resultImg.style.display = 'none';

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 300000);

    try {
        let refImages = [];
        if (refImageInput.files.length > 0) {
            refImages = await Promise.all(
                Array.from(refImageInput.files).map(fileToBase64)
            );
        }

        const payload = {
            prompt: prompt,
            resolution: resolution,
            reference_images_base64: refImages.length > 0 ? refImages : null
        };

        const response = await fetch(`${baseUrl}/v1/generate_image`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            },
            body: JSON.stringify(payload),
            signal: controller.signal
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(`Server error ${response.status}: ${errorText}`);
        }

        const data = await response.json();
        resultImg.src = `data:image/png;base64,${data.image_base64}`;
        resultImg.style.display = 'block';
        statusDiv.textContent = 'Done';
    } catch (error) {
        clearTimeout(timeoutId);
        statusDiv.textContent = `Error: ${error.message}`;
        console.error(error);
    }
