import hmac
import os
from typing import List, Optional

from fastapi import Header, HTTPException

from omnigen.config import AuthConfig


class APIKeyAuth:
    def __init__(self, keys: List[str]):
        self.keys = [k.strip() for k in keys if k and k.strip()]

    @classmethod
    def from_env(cls, cfg: AuthConfig) -> "APIKeyAuth":
        raw = os.environ.get(cfg.api_keys_env, "")
        keys = [k for k in raw.split(",") if k.strip()]
        return cls(keys)

    def verify(self, token: str) -> str:
        for key in self.keys:
            if hmac.compare_digest(token, key):
                return key
        raise HTTPException(status_code=403, detail="Invalid API Key")


def require_api_key(auth: APIKeyAuth):
    def dep(authorization: Optional[str] = Header(default=None)) -> str:
        if not authorization:
            raise HTTPException(status_code=401, detail="Missing Authorization header")
        parts = authorization.split()
        if len(parts) != 2 or parts[0].lower() != "bearer":
            raise HTTPException(status_code=401, detail="Invalid Authorization header format")
        token = parts[1]
        return auth.verify(token)
    return dep


