import time
import threading
from dataclasses import dataclass
from typing import Dict

from omnigen.config import RateLimitConfig

@dataclass
class Bucket:
    tokens: float
    updated: float

class RateLimiter:
    def __init__(self, per_minute: int):
        self.capacity = per_minute
        self.refill_rate = per_minute / 60.0
        self.buckets: Dict[str, Bucket] = {}
        self.lock = threading.Lock()
        self.last_cleanup = time.monotonic()

    @classmethod
    def from_cfg(cls, cfg: RateLimitConfig) -> "RateLimiter":
        return cls(per_minute=cfg.requests_per_minute)

    def allow(self, key: str) -> None:
        now = time.monotonic()
        with self.lock:
            if now - self.last_cleanup > 60:
                self._cleanup(now)

            b = self.buckets.get(key)
            if b is None:
                b = Bucket(tokens=self.capacity, updated=now)
                self.buckets[key] = b

            elapsed = now - b.updated
            b.tokens = min(self.capacity, b.tokens + elapsed * self.refill_rate)
            b.updated = now

            if b.tokens < 1.0:
                raise Exception("Rate limit exceeded")

            b.tokens -= 1.0

    def _cleanup(self, now: float):
        keys_to_remove = [k for k, v in self.buckets.items() if (now - v.updated) > 300]
        for k in keys_to_remove:
            del self.buckets[k]
        self.last_cleanup = now

def rate_limit_dep(limiter: RateLimiter):
    def dep(api_key: str) -> str:
        limiter.allow(api_key)
        return api_key
    return dep


