class RequestTooLarge(Exception):
    pass

class BodySizeLimitMiddleware:
    def __init__(self, app, max_bytes: int):
        self.app = app
        self.max_bytes = max_bytes

    async def __call__(self, scope, receive, send):
        if scope["type"] == "http":
            headers = dict(scope.get("headers") or [])
            cl = headers.get(b"content-length")
            if cl:
                size = int(cl)
                if size > self.max_bytes:
                    raise RequestTooLarge()
        await self.app(scope, receive, send)

@dataclass
class SessionEntry:
    signature: str
    updated: float

class SessionStore:
    def __init__(self, ttl_seconds: int):
        self.ttl = ttl_seconds
        self.data: dict = {}
        self.lock = threading.Lock()

    def _prune(self) -> None:
        now = time.monotonic()
        dead = [k for k, v in self.data.items() if (now - v.updated) > self.ttl]
        for k in dead:
            del self.data[k]

    def get(self, session_id: str) -> Optional[str]:
        with self.lock:
            self._prune()
            ent = self.data.get(session_id)
            return ent.signature if ent else None

    def set(self, session_id: str, signature: str) -> None:
        with self.lock:
            self.data[session_id] = SessionEntry(signature=signature, updated=time.monotonic())

def _decode_b64_image(b64: str) -> Image.Image:
    try:
        raw = base64.b64decode(b64, validate=True)
        img = Image.open(io.BytesIO(raw))
        return img
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Invalid image data: {str(e)}")

def _parse_resolution(value: Optional[MediaResolution]) -> MediaResolution:
    return value or MediaResolution.high

def _parse_decoding(opt, default_strategy: str) -> DecodingParams:
    p = DecodingParams(strategy=opt.strategy or default_strategy)
    if opt.temperature is not None:
        p.temperature = opt.temperature
    if opt.top_p is not None:
        p.top_p = opt.top_p
    if opt.top_k is not None:
        p.top_k = opt.top_k
    if opt.beam_size is not None:
        p.beam_size = opt.beam_size
    return p

