@app.post("/v1/generate_image", response_model=GenerationResponse)
def generate_image(req: GenerateImageRequest, api_key: str = require_api_key(auth)):
    resolution = _parse_resolution(req.resolution)
    decoding = _parse_decoding(req.decoding, cfg.inference.decoding.strategy)

    ref = None
    if req.reference_images_base64:
        ref = [_decode_b64_image(x).convert("RGB") for x in req.reference_images_base64]

    result = engine.generate_image(
        prompt=req.prompt,
        resolution=resolution,
        reference_images=ref,
        decoding=decoding,
        include_thought=req.include_thought,
        enable_grounding=req.enable_grounding,
        grounding_request=req.grounding_request,
        session_signature=req.session_signature,
        content_type=req.content_type
    )
    return result

@app.post("/v1/edit_image", response_model=GenerationResponse)
def edit_image(req: EditImageRequest, api_key: str = require_api_key(auth)):
    resolution = _parse_resolution(req.resolution)
    decoding = _parse_decoding(req.decoding, cfg.inference.decoding.strategy)

    img = _decode_b64_image(req.image_base64).convert("RGB")
    mask = _decode_b64_image(req.mask_base64).convert("L")

    result = engine.edit_image(
        prompt=req.prompt,
        image=img,
        mask=mask,
        resolution=resolution,
        decoding=decoding,
        grounding_request=req.grounding_request,
        session_signature=req.session_signature,
        content_type=req.content_type
    )
    return result

@app.post("/v1/multi_turn_session", response_model=MultiTurnSessionResponse)
def multi_turn_session(req: MultiTurnSessionRequest, api_key: str = require_api_key(auth)):
    session_id = req.session_id or str(uuid.uuid4())
    stored_sig = session_store.get(session_id)
    sig = req.session_signature or stored_sig

    if req.operation == "generate":
        resolution = _parse_resolution(req.resolution)
        decoding = _parse_decoding(None, cfg.inference.decoding.strategy)
        result = engine.generate_image(
            prompt=req.prompt or "",
            resolution=resolution,
            reference_images=None,
            decoding=decoding,
            session_signature=sig,
            content_type="image/png"
        )
        session_store.set(session_id, result.signature)
        return MultiTurnSessionResponse(session_id=session_id, result=result)

    raise HTTPException(status_code=400, detail="Invalid operation")

