import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from typing import Tuple, Optional

def rotate_half(x: torch.Tensor) -> torch.Tensor:
    orig_shape = x.shape
    x2d = x.reshape(-1, orig_shape[-1])
    xpair = x2d.reshape(-1, orig_shape[-1] // 2, 2)
    x1 = xpair[:, :, 0]
    x2 = xpair[:, :, 1]
    rot = torch.stack((-x2, x1), dim=-1).reshape(-1, orig_shape[-1])
    return rot.reshape(orig_shape)

class RotaryEmbedding(nn.Module):
    def __init__(self, dim: int, theta: float = 10000.0, scaling_factor: float = 1.0):
        super().__init__()
        inv_freq = 1.0 / (theta ** (torch.arange(0, dim, 2).float() / dim))
        self.register_buffer("inv_freq", inv_freq)
        self.scaling_factor = scaling_factor
        self._cache = {}

    def get_cos_sin(self, seq_len: int, device: torch.device, dtype: torch.dtype) -> Tuple[torch.Tensor, torch.Tensor]:
        key = (seq_len, device.type, device.index, dtype)
        cached = self._cache.get(key)
        if cached is not None:
            return cached
        t = torch.arange(seq_len, device=device, dtype=self.inv_freq.dtype) / self.scaling_factor
        freqs = torch.einsum("i,j->ij", t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        cos = emb.cos().to(dtype)
        sin = emb.sin().to(dtype)
        self._cache[key] = (cos, sin)
        return cos, sin

def apply_rotary_emb(x: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor) -> torch.Tensor:
    cos = cos[:, None, :, :]
    sin = sin[:, None, :, :]
    return (x * cos) + (rotate_half(x) * sin)

class MultiQueryAttention(nn.Module):
    def __init__(self, d_model: int, num_heads: int, num_kv_heads: int, dropout: float, rope: RotaryEmbedding):
        super().__init__()
        self.num_heads = num_heads
        self.num_kv_heads = num_kv_heads
        self.head_dim = d_model // num_heads
        self.scale = 1.0 / math.sqrt(self.head_dim)
        self.rope = rope

        self.q_proj = nn.Linear(d_model, num_heads * self.head_dim, bias=False)
        self.k_proj = nn.Linear(d_model, num_kv_heads * self.head_dim, bias=False)
        self.v_proj = nn.Linear(d_model, num_kv_heads * self.head_dim, bias=False)
        self.o_proj = nn.Linear(num_heads * self.head_dim, d_model, bias=False)

        self.attn_dropout = nn.Dropout(dropout)
        self.resid_dropout = nn.Dropout(dropout)

    def forward(self, hidden_states, attention_mask=None, past_key_value=None, use_cache=False):
        bsz, q_len, _ = hidden_states.shape
        device = hidden_states.device

        q = self.q_proj(hidden_states).view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2)
        k = self.k_proj(hidden_states).view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)
        v = self.v_proj(hidden_states).view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)

        past_len = past_key_value[0].shape[2] if past_key_value is not None else 0
        pos = torch.arange(past_len, past_len + q_len, device=device, dtype=torch.long)
        position_ids = pos.unsqueeze(0).expand(bsz, -1)

        cos_all, sin_all = self.rope.get_cos_sin(past_len + q_len, device, hidden_states.dtype)
        cos = cos_all[position_ids]
        sin = sin_all[position_ids]

        q = apply_rotary_emb(q, cos, sin)
        k = apply_rotary_emb(k, cos, sin)

        if past_key_value is not None:
            k = torch.cat([past_key_value[0], k], dim=2)
            v = torch.cat([past_key_value[1], v], dim=2)
        present = (k, v) if use_cache else None

        kv_len = k.shape[2]

        if self.num_kv_heads < self.num_heads:
            repeat_factor = self.num_heads // self.num_kv_heads
            k_attn = k.repeat_interleave(repeat_factor, dim=1)
            v_attn = v.repeat_interleave(repeat_factor, dim=1)
        else:
            k_attn = k
            v_attn = v

        attn_weights = torch.matmul(q, k_attn.transpose(-2, -1)) * self.scale

        key_pos = torch.arange(kv_len, device=device, dtype=torch.long)
        query_pos = torch.arange(past_len, past_len + q_len, device=device, dtype=torch.long)
        causal = key_pos.unsqueeze(0) <= query_pos.unsqueeze(1)
        attn_weights = attn_weights.masked_fill(~causal.unsqueeze(0).unsqueeze(0), float("-inf"))

        if attention_mask is not None:
            attention_mask = attention_mask.to(torch.bool)
            attn_weights = attn_weights.masked_fill(~attention_mask[:, None, None, :], float("-inf"))

        attn_probs = F.softmax(attn_weights, dim=-1, dtype=torch.float32).to(attn_weights.dtype)
        attn_probs = self.attn_dropout(attn_probs)

        attn_output = torch.matmul(attn_probs, v_attn)
        attn_output = attn_output.transpose(1, 2).contiguous().view(bsz, q_len, self.num_heads * self.head_dim)
        attn_output = self.o_proj(attn_output)
        attn_output = self.resid_dropout(attn_output)

        return attn_output, present


