from typing import Dict

class MultiModalEmbedding(nn.Module):
    def __init__(self, d_model: int, vocab_sizes: Dict[str, int], offsets: Dict[str, int], dropout: float):
        super().__init__()
        self.d_model = d_model
        self.offsets = offsets
        self.text = nn.Embedding(vocab_sizes["text"], d_model)
        self.control = nn.Embedding(vocab_sizes["control"], d_model)
        self.image = nn.Embedding(vocab_sizes["image"], d_model)
        self.audio = nn.Embedding(vocab_sizes["audio"], d_model)
        self.video = nn.Embedding(vocab_sizes["video"], d_model)
        self.modality_type = nn.Embedding(5, d_model)
        self.dropout = nn.Dropout(dropout)

    def forward(self, input_ids: torch.Tensor, modality_ids: torch.Tensor) -> torch.Tensor:
        device = input_ids.device
        bsz, seq_len = input_ids.shape
        out = torch.zeros((bsz, seq_len, self.d_model), device=device, dtype=self.text.weight.dtype)

        def fill(modality: str, modality_index: int, emb: nn.Embedding) -> None:
            mask = modality_ids == modality_index
            if mask.any():
                local = (input_ids[mask] - self.offsets[modality]).to(torch.long)
                out[mask] = emb(local)

        fill("text", 0, self.text)
        fill("control", 1, self.control)
        fill("image", 2, self.image)
        fill("audio", 3, self.audio)
        fill("video", 4, self.video)

        out = out + self.modality_type(modality_ids)
        return self.dropout(out)


